package com.greenocean.backend;
import org.flywaydb.core.Flyway;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import java.util.*;import static org.assertj.core.api.Assertions.*;
class PhaseO4MigrationTest extends MigrationTestSupport {
 @Test void populatedUpgradeRollsBackAndRetriesWithoutAwardingLegacyPercentages(){String url=System.getenv("GREENOCEAN_TEST_DB_URL"),schema="qa_o4_upgrade_"+UUID.randomUUID().toString().replace("-","");var source=new DriverManagerDataSource(url,System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD",""));Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("65").load().migrate();var db=new JdbcTemplate(new DriverManagerDataSource(url+(url.contains("?")?"&":"?")+"currentSchema="+schema+",public",System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD","")));try{UUID user=db.queryForObject("INSERT INTO users(email,password_hash,status) VALUES ('o4-upgrade@example.test','synthetic','ACTIVE') RETURNING id",UUID.class),path=db.queryForObject("SELECT id FROM guided_growth_paths ORDER BY id LIMIT 1",UUID.class);db.update("INSERT INTO user_growth_path_progress(user_id,path_id,progress,completed,legacy_progress) VALUES (?,?,100,TRUE,100)",user,path);var before=db.queryForList("SELECT to_jsonb(t)::text AS record FROM user_growth_path_progress t ORDER BY user_id,path_id");db.execute("CREATE TABLE growth_reward_rules(synthetic_conflict INTEGER)");assertThatThrownBy(()->Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).load().migrate()).isInstanceOf(Exception.class);assertThat(db.queryForObject("SELECT count(*) FROM information_schema.tables WHERE table_schema=? AND table_name='growth_reward_ledger'",Integer.class,schema)).isZero();db.execute("DROP TABLE growth_reward_rules");Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).load().migrate();assertThat(db.queryForList("SELECT to_jsonb(t)::text AS record FROM user_growth_path_progress t ORDER BY user_id,path_id")).isEqualTo(before);assertThat(db.queryForObject("SELECT count(*) FROM growth_reward_ledger",Integer.class)).isZero();assertThat(db.queryForObject("SELECT count(*) FROM growth_learning_badges",Integer.class)).isZero();}finally{db.execute("DROP SCHEMA "+schema+" CASCADE");}}
}
